def min_path(g):
    m, n = len(g), len(g[0])
    dp = [float('inf')] * n
    dp[0] = 0
    for i in range(m):
        for j in range(n):
            left = dp[j - 1] if j else float('inf')
            dp[j] = g[i][j] + min(dp[j], left)
    return dp[-1]

def knapsack(items, W):
    dp = [0] * (W + 1)
    for wt, val in items:
        for w in range(W, wt - 1, -1):
            dp[w] = max(dp[w], dp[w - wt] + val)
    return dp[W]

